document.addEventListener('click',e=>{const item=e.target.closest('[data-alert-index]');if(item&&overviewAlerts[item.dataset.alertIndex])showAlertDetail(overviewAlerts[item.dataset.alertIndex]);const card=e.target.closest('#stats [data-card]');if(card){const view={active_alerts:'alerts',total_alerts:'alerts',nearby_safe_zones:'safezones',nearby_evacuation_centers:'safezones',total_safe_zones:'safezones',total_evacuation_centers:'safezones',weather_status:'weather',total_hazards:'hazards',total_reports:'reports',total_municipalities:'municipalities',total_residents:'users'}[card.dataset.card];if(view)openAdminView(view);}});
