const municipalityPanel=document.getElementById('municipalityPanel'),municipalityForm=document.getElementById('municipalityForm'),municipalityDetails=document.getElementById('municipalityDetails');
const municipalitiesById=new Map();
function actionIcon(name){const icons={view:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="3"/></svg>',edit:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m16.5 3.5 4 4L8 20H4v-4L16.5 3.5Z"/><path d="m14 6 4 4"/></svg>',send:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M22 2 11 13"/><path d="m22 2-7 20-4-9-9-4 20-7Z"/></svg>',read:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>',activate:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>',disable:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m5.7 5.7 12.6 12.6"/></svg>',download:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11"/><path d="m7 10 5 5 5-5"/><path d="M5 21h14"/></svg>',delete:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M6 7l1 14h10l1-14"/><path d="M9 7V4h6v3"/></svg>'};return icons[name]||'';}
function forceMunicipalityModalLayout(){
  const panelStyles={position:'fixed',inset:'0','z-index':'99999',width:'100vw',height:'100vh','min-height':'100vh',display:'flex','align-items':'center','justify-content':'center','overflow-y':'auto',background:'rgba(15,23,42,.62)',padding:'1rem','backdrop-filter':'blur(14px)'};
  Object.entries(panelStyles).forEach(([key,value])=>municipalityPanel.style.setProperty(key,value,'important'));
  const dialog=municipalityPanel.querySelector('.modal-dialog');
  if(dialog){
    const dialogStyles={position:'relative',top:'auto',left:'auto',transform:'none',width:'min(100%,40rem)','max-height':'calc(100vh - 2rem)',overflow:'hidden',border:'1px solid rgba(255,255,255,.82)','border-radius':'1.35rem',background:'#fff','box-shadow':'0 34px 100px rgba(2,6,23,.38),0 0 0 1px rgba(15,23,42,.04)'};
    Object.entries(dialogStyles).forEach(([key,value])=>dialog.style.setProperty(key,value,'important'));
  }
}
function showMunicipalityPanel(){if(municipalityPanel.parentElement!==document.body)document.body.appendChild(municipalityPanel);document.body.classList.add('modal-open');municipalityPanel.classList.remove('hidden');municipalityPanel.classList.add('flex');forceMunicipalityModalLayout();}
function hideMunicipalityPanel(){municipalityPanel.classList.add('hidden');municipalityPanel.classList.remove('flex');municipalityPanel.style.setProperty('display','none','important');document.body.classList.remove('modal-open');}
function municipalityDetailsCard(item,mode='view'){const created=item.created_at?new Date(item.created_at).toLocaleString():'Not available',updated=item.updated_at?new Date(item.updated_at).toLocaleString():'Not available',status=item.status||'inactive';return `<article class="municipality-details-card ${status==='active'?'is-active':'is-inactive'}"><header><span class="municipality-details-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 21V9l8-6 8 6v12"/><path d="M9 21v-7h6v7"/><path d="M3 21h18"/></svg></span><div><span>${mode==='edit'?'Editing record':'Municipality details'}</span><h3>${escapeText(item.municipality_name||'Unnamed municipality')}</h3></div></header><div class="municipality-details-status"><b>${escapeText(status)}</b><small>${mode==='edit'?'Current saved details are shown below.':'Official municipality record'}</small></div><section><span>Description</span><p>${escapeText(item.description||'No description provided')}</p></section><dl><div><dt>Created</dt><dd>${escapeText(created)}</dd></div><div><dt>Last updated</dt><dd>${escapeText(updated)}</dd></div></dl></article>`;}
function municipalityFormFields(){return {id:municipalityForm.querySelector('[name="id"]'),name:municipalityForm.querySelector('[name="municipality_name"]'),description:municipalityForm.querySelector('[name="description"]'),status:municipalityForm.querySelector('[name="status"]')};}
function fillMunicipalityInputs(item=null){const fields=municipalityFormFields();fields.id.value=item?.id??'';fields.name.value=item?.municipality_name??'';fields.description.value=item?.description??'';fields.status.value=item?.status||'active';}
function openMunicipalityForm(item=null){showMunicipalityPanel();municipalityDetails.classList.toggle('hidden',!item);if(item){municipalityDetails.innerHTML=municipalityDetailsCard(item,'edit');}else{municipalityDetails.innerHTML='';}municipalityForm.classList.remove('hidden');municipalityForm.style.removeProperty('display');municipalityForm.reset();fillMunicipalityInputs(item);document.getElementById('municipalityPanelTitle').textContent=item?'Edit municipality':'Add municipality';document.getElementById('municipalityFormError').classList.add('hidden');}
function openMunicipalityView(item){showMunicipalityPanel();municipalityForm.classList.add('hidden');municipalityForm.style.setProperty('display','none','important');municipalityDetails.classList.remove('hidden');document.getElementById('municipalityPanelTitle').textContent='Municipality details';municipalityDetails.innerHTML=municipalityDetailsCard(item,'view');}
function setMunicipalityFormBusy(busy){municipalityForm.querySelectorAll('input,textarea,select,button').forEach(field=>field.disabled=busy);}
async function openMunicipalityEdit(id){const cached=municipalitiesById.get(String(id));openMunicipalityForm(cached||{id,municipality_name:'',description:'',status:'active'});document.getElementById('municipalityPanelTitle').textContent='Edit municipality';fillMunicipalityInputs(cached||{id});setMunicipalityFormBusy(true);municipalityFormFields().name.placeholder='Loading municipality...';if(!cached){municipalityDetails.classList.remove('hidden');municipalityDetails.innerHTML='<article class="municipality-details-card is-loading"><p>Loading municipality details...</p></article>';}try{const item=await Api.get(`/municipalities/${id}`);municipalitiesById.set(String(item.id),item);openMunicipalityForm(item);}catch(err){if(!cached)hideMunicipalityPanel();toast(err.message);}finally{municipalityFormFields().name.placeholder='Enter municipality name';setMunicipalityFormBusy(false);}}
async function loadMunicipalities(){try{const rows=await Api.get('/municipalities');municipalitiesById.clear();rows.forEach(m=>municipalitiesById.set(String(m.id),m));document.getElementById('municipalitiesTable').innerHTML=rows.map(m=>{const status=m.status||'inactive',description=m.description||'No operational notes recorded.',name=escapeText(m.municipality_name);return `<tr class="municipality-row border-t"><td class="municipality-name-cell p-4"><div class="municipality-name-block"><span class="municipality-row-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 21V9l8-6 8 6v12"/><path d="M9 21v-7h6v7"/><path d="M3 21h18"/></svg></span><div><strong>${name}</strong><small>Municipal jurisdiction</small></div></div></td><td class="municipality-description-cell p-4"><span>${escapeText(description)}</span></td><td class="municipality-status-cell p-4"><span class="municipality-status-pill ${status==='active'?'is-active':'is-inactive'}"><i></i>${escapeText(status)}</span></td><td class="municipality-actions-cell p-4 text-right"><div class="municipality-actions"><button data-action="view" data-id="${m.id}" class="municipality-action view" title="View municipality" aria-label="View ${name}">${actionIcon('view')}</button><button data-action="edit" data-id="${m.id}" class="municipality-action edit" title="Edit municipality" aria-label="Edit ${name}">${actionIcon('edit')}</button><button data-action="delete" data-id="${m.id}" class="municipality-action delete" title="Delete municipality" aria-label="Delete ${name}">${actionIcon('delete')}</button></div></td></tr>`;}).join('')||'<tr><td colspan="4" class="p-8 text-center text-slate-500">No municipalities found.</td></tr>';}catch(e){toast(e.message);}}
document.getElementById('addMunicipalityBtn')?.addEventListener('click',()=>openMunicipalityForm());document.getElementById('closeMunicipalityPanel')?.addEventListener('click',hideMunicipalityPanel);
document.getElementById('municipalitiesTable')?.addEventListener('click',async e=>{const button=e.target.closest('button[data-action]');if(!button)return;try{if(button.dataset.action==='edit'){await openMunicipalityEdit(button.dataset.id);return;}const item=await Api.get(`/municipalities/${button.dataset.id}`);municipalitiesById.set(String(item.id),item);if(button.dataset.action==='view'){openMunicipalityView(item);}else if(button.dataset.action==='delete'&&await confirmAction(`Delete ${item.municipality_name}? This cannot be undone.`)){await Api.delete(`/municipalities/${item.id}`);toast('Municipality deleted');loadMunicipalities();overview();}}catch(err){toast(err.message);}});
municipalityPanel?.addEventListener('click',e=>{if(e.target===municipalityPanel||e.target.closest('[data-modal-close]'))hideMunicipalityPanel();});
municipalityForm?.addEventListener('submit',async e=>{e.preventDefault();const error=document.getElementById('municipalityFormError'),data=Object.fromEntries(new FormData(e.target)),id=data.id;delete data.id;error.classList.add('hidden');try{if(id)await Api.put(`/municipalities/${id}`,data);else await Api.post('/municipalities',data);hideMunicipalityPanel();toast(id?'Municipality updated':'Municipality added');loadMunicipalities();overview();}catch(err){error.textContent=err.message;error.classList.remove('hidden');}});
