function safeZoneRadius(s){return Number(s.perimeter_radius_m)||SAFE_ZONE_DEFAULT_RADIUS;}
async function annotateFacilitySafety(rows){try{if(!safeZoneHazardCache)safeZoneHazardCache=await Api.get('/hazards');}catch{safeZoneHazardCache=[];}const zones=rows.filter(r=>r.facility_type==='safe_zone');await Promise.all(rows.map(async s=>{const here=L.latLng(s.latitude,s.longitude),point=[Number(s.longitude),Number(s.latitude)];const others=zones.filter(z=>!(z.facility_type===s.facility_type&&String(z.id)===String(s.id))).map(z=>({name:z.facility_name,radius:safeZoneRadius(z),distance:here.distanceTo([z.latitude,z.longitude])})).sort((a,b)=>a.distance-b.distance);const hazards=(safeZoneHazardCache||[]).filter(h=>h.geojson_data&&CaviteGIS.pointInGeometry(h.geojson_data,point)).map(h=>({name:h.hazard_name,type:hazardTypeLabel(h.hazard_type),risk:h.risk_level}));let geo=[];try{geo=await CaviteGIS.geohazardsAt(Number(s.latitude),Number(s.longitude));}catch{}s.safety={insideZones:others.filter(z=>z.distance<=z.radius),nearestZone:others[0]||null,hazards,geo};}));return rows;}
function facilitySafetyVerdict(s){const safety=s.safety;if(!safety)return null;const exposed=safety.hazards.length||safety.geo.some(g=>g.level==='high');if(s.facility_type==='evacuation_center'){if(exposed)return{tone:'danger',label:'In a hazard area'};if(safety.insideZones.length)return{tone:'good',label:'Inside a safe zone'};if(safety.nearestZone&&safety.nearestZone.distance<=SAFE_ZONE_CATCHMENT_M)return{tone:'warn',label:`Near safe zone (${Math.round(safety.nearestZone.distance)} m)`};return{tone:'warn',label:'Outside safe zones'};}return exposed?{tone:'danger',label:'In a hazard area'}:safety.geo.length?{tone:'warn',label:'Moderate geohazard'}:{tone:'good',label:'No hazard overlap'};}
function facilitySafetyDetails(s){const safety=s.safety;if(!safety)return'';const verdict=facilitySafetyVerdict(s),items=[];if(s.facility_type==='evacuation_center')items.push(safety.insideZones.length?`Inside the perimeter of <b>${safety.insideZones.map(z=>escapeText(z.name)).join(', ')}</b>.`:safety.nearestZone?`Nearest safe zone: <b>${escapeText(safety.nearestZone.name)}</b>, ${(safety.nearestZone.distance/1000).toFixed(2)} km away (outside its ${safety.nearestZone.radius} m perimeter).`:'No safe zone recorded nearby.');else items.push(`Perimeter radius <b>${safeZoneRadius(s)} m</b>; residents within ${SAFE_ZONE_CATCHMENT_M/1000} km (about 15 minutes on foot) should gather here.`);items.push(safety.hazards.length?`Overlaps hazard: ${safety.hazards.map(h=>`<b>${escapeText(h.name)}</b> (${escapeText(h.type)}, ${escapeText(hazardRiskLabel(h.risk))})`).join(', ')}.`:'Outside every recorded hazard area.');if(safety.geo.length)items.push(`Geohazard reference: ${safety.geo.map(g=>escapeText(g.label)).join('; ')}.`);return `<section class="facility-safety is-${verdict.tone}"><span>Safety check · ${escapeText(verdict.label)}</span><ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul></section>`;}
function facilitySafetyCell(s){const verdict=facilitySafetyVerdict(s);return verdict?`<span class="safety-pill is-${verdict.tone}" title="${escapeText(facilitySafetyDetails(s).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim())}">${escapeText(verdict.label)}</span>`:'<span class="muted-note">Checking...</span>';}
function updateFacilitySafetySummary(rows){const box=document.getElementById('facilitySafetySummary');if(!box)return;const centers=rows.filter(r=>r.facility_type==='evacuation_center'&&r.safety),inside=centers.filter(r=>r.safety.insideZones.length).length,exposed=rows.filter(r=>r.safety&&facilitySafetyVerdict(r)?.tone==='danger');box.innerHTML=`<article class="is-good"><strong>${inside}/${centers.length}</strong><span>evacuation centers inside a safe-zone perimeter</span></article><article class="${exposed.length?'is-danger':'is-good'}"><strong>${exposed.length}</strong><span>facilit${exposed.length===1?'y sits':'ies sit'} inside a hazard area${exposed.length?`: ${exposed.slice(0,3).map(r=>escapeText(r.facility_name)).join(', ')}${exposed.length>3?'...':''}`:''}</span></article><article><strong>${rows.filter(r=>r.facility_type==='safe_zone').length}</strong><span>safe zones with a mapped perimeter (default ${SAFE_ZONE_DEFAULT_RADIUS} m)</span></article>`;}
function safeZoneActionIcon(type){const icons={view:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></svg>',route:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM19 9a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM7 17c5 0 3-10 10-10"/></svg>',edit:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4l10.5-10.5a2.1 2.1 0 0 0-3-3L5 17v3Z"/><path d="m14 7 3 3"/></svg>',delete:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V5h6v2m-8 0 1 13h8l1-13"/></svg>'};return icons[type]||'';}
