function drawSafeZoneRoute(start,destination,road){safeZoneRouteLayer.clearLayers();const routeColor=destination.facility_type==='evacuation_center'?'#2563eb':'#059669',line=L.geoJSON(road.geojson_data,{style:{color:'#ffffff',weight:9,opacity:.95,lineCap:'round',lineJoin:'round'}}).addTo(safeZoneRouteLayer),main=L.geoJSON(road.geojson_data,{style:{color:routeColor,weight:5,opacity:.95,lineCap:'round',lineJoin:'round'}}).addTo(safeZoneRouteLayer);L.circleMarker([start.latitude,start.longitude],{radius:9,color:'#fff',weight:3,fillColor:'#2563eb',fillOpacity:1}).bindPopup('Your current location').addTo(safeZoneRouteLayer);L.marker([destination.latitude,destination.longitude],{icon:facilityMarkerIcon(destination,false),zIndexOffset:800}).bindPopup(safeZoneMapCard(destination,false),{className:'safe-zone-popup',maxWidth:360,minWidth:300}).addTo(safeZoneRouteLayer);safeZoneMap.fitBounds(main.getBounds().extend([start.latitude,start.longitude]).extend([destination.latitude,destination.longitude]),{padding:[55,55],maxZoom:16});}
