async function routeToSafeZone(item=null){focusSafeZoneMap();const mode=safeZoneRouteMode,label=safeZoneRouteLabels[mode]||'Route';updateSafeZoneRouteSummary(`<strong>Calculating ${label.toLowerCase()}...</strong><span>Please allow location access when prompted.</span>`,true);try{const start=await currentPosition(),destination=item||(await nearestCombinedFacility(start));if(!destination)throw new Error('No safety facility found near your location');const road=await Api.get(`/evacuation-routes/road?mode=${mode}&start_lat=${start.latitude}&start_lng=${start.longitude}&end_lat=${destination.latitude}&end_lng=${destination.longitude}`),distance=(road.distance_m/1000).toFixed(1),duration=road.duration_s?`${Math.ceil(road.duration_s/60)} min`:'Unavailable',metricLabels=safeZoneRouteMetricLabels[road.mode]||safeZoneRouteMetricLabels[mode]||['Distance','Estimated time'],sourceText=road.source==='osrm_mode_estimate'?'Road distance with mode-based time estimate':`${safeZoneRouteLabels[road.mode]||label} estimate using mode-specific speed`;drawSafeZoneRoute(start,destination,road);focusSafeZoneMap();updateSafeZoneRouteSummary(`<div><span>${escapeText(safeZoneRouteLabels[road.mode]||label)}</span><strong>${escapeText(destination.facility_name||destination.safezone_name||destination.center_name)}</strong></div><dl><div><dt>${metricLabels[0]}</dt><dd>${distance} km</dd></div><div><dt>${metricLabels[1]}</dt><dd>${duration}</dd></div></dl><p>${sourceText}</p>`,true);toast(`${label} ready: ${destination.facility_name||destination.safezone_name||destination.center_name}`);}catch(error){updateSafeZoneRouteSummary(`<strong>Route unavailable</strong><span>${escapeText(error.message)}</span>`,true);toast(error.message);}}
