function historyBarangayChips(list,limit=3){const shown=list.slice(0,limit).map(b=>`<span class="barangay-chip">${escapeText(b)}</span>`).join(''),more=list.length>limit?`<span class="barangay-chip is-more" title="${escapeText(list.slice(limit).join(', '))}">+${list.length-limit}</span>`:'';return shown+more;}
function renderHistoricalSummary(rows){const box=document.getElementById('historicalSummary');if(!box)return;const events=new Set(rows.map(r=>r.event_name||r.title)),municipalities=new Set(rows.filter(r=>r.municipality_id).map(r=>r.municipality_id)),sum=key=>rows.reduce((total,r)=>total+Number(r[key]||0),0),byTown={};rows.forEach(r=>{if(r.municipality_id)byTown[r.municipality_name]=(byTown[r.municipality_name]||0)+Number(r.affected_barangay_count||0);});const top=Object.entries(byTown).sort((a,b)=>b[1]-a[1]).slice(0,3);box.innerHTML=`<article><span>Disaster events</span><strong>${events.size}</strong><small>${rows.length} municipal record${rows.length===1?'':'s'}</small></article><article><span>Affected barangays</span><strong>${sum('affected_barangay_count').toLocaleString()}</strong><small>across ${municipalities.size} municipalit${municipalities.size===1?'y':'ies'}</small></article><article class="is-danger"><span>Casualties</span><strong>${sum('casualties').toLocaleString()}</strong><small>${sum('injured').toLocaleString()} injured</small></article><article><span>Evacuated families</span><strong>${sum('evacuated_families').toLocaleString()}</strong><small>as recorded in SitReps</small></article><article class="is-wide"><span>Most affected (barangay count)</span><div class="chip-row">${top.map(([name,count])=>`<span class="type-chip" style="--chip:#2563eb">${escapeText(name)} ×${count}</span>`).join('')||'<span class="muted-note">No records</span>'}</div></article>`;}
